<script lang="ts">
  /**
   * Footer -> About: version, the MIT license, the repository, the fan content disclaimer, the
 * Support / Buy me a coffee links and
   * THIRD_PARTY_NOTICES.md (generated by scripts/gen-notices.sh). Both texts are bundled at
   * build time; the notices (~370 kB) are a separate chunk loaded only when the dialog opens.
   */
  import Info from '@lucide/svelte/icons/info';
  import LifeBuoy from '@lucide/svelte/icons/life-buoy';
  import Coffee from '@lucide/svelte/icons/coffee';
  import { LINKS, openLink } from '@/lib/links';
  import * as Dialog from '@/components/ui/dialog';
  import { Button } from '@/components/ui/button';
  import { app } from '@/lib/stores/app.svelte';
  import { FAN_DISCLAIMER, LOCAL_FILES_NOTE, REPO_URL } from '@/lib/legal';
  import license from '../../../../LICENSE?raw';

  let { open = $bindable(false) }: { open: boolean } = $props();
  let notices = $state<string | null>(null);
  let failed = $state(false);

  $effect(() => {
    if (!open || notices !== null) return;
    let stale = false;
    import('../../../../THIRD_PARTY_NOTICES.md?raw')
      .then((m) => !stale && (notices = m.default))
      .catch(() => !stale && (failed = true));
    return () => (stale = true);
  });

  const version = $derived(app.overview?.app_version ?? null);
</script>

<Dialog.Root bind:open>
  <Dialog.Content class="max-h-[85vh] overflow-y-auto sm:max-w-2xl">
    <Dialog.Header>
      <Dialog.Title class="flex items-center gap-2"><Info class="text-primary size-5" aria-hidden="true" /> About StarOrg Codex</Dialog.Title>
      <Dialog.Description>
        {version ? `Version ${version}` : 'Version unknown'} · MIT License · <span class="mono select-all">{REPO_URL}</span>
      </Dialog.Description>
    </Dialog.Header>
    <div class="grid gap-3 text-[13px]">
      <section aria-labelledby="about-disclaimer" class="rounded-md border p-2.5">
        <h3 id="about-disclaimer" class="font-medium">Fan project</h3>
        <p class="text-muted-foreground mt-1 text-[12.5px]">{FAN_DISCLAIMER}</p>
        <p class="text-muted-foreground mt-2 text-[12.5px]">{LOCAL_FILES_NOTE}</p>
      </section>
      <section aria-labelledby="about-support" class="rounded-md border p-2.5">
        <h3 id="about-support" class="font-medium">Support</h3>
        <p class="text-muted-foreground mt-1 text-[12.5px]">
          Questions, bugs and ideas: the Discord server. If the app saves you time, you can buy me a coffee. Both open in
          your browser; the app itself sends nothing.
        </p>
        <div class="mt-2 flex flex-wrap gap-2">
          <Button variant="outline" size="sm" title={LINKS.support.url} onclick={() => openLink('support')}>
            <LifeBuoy aria-hidden="true" /> Support on Discord
          </Button>
          <Button variant="outline" size="sm" title={LINKS.donate.url} onclick={() => openLink('donate')}>
            <Coffee aria-hidden="true" /> {LINKS.donate.label}
          </Button>
        </div>
      </section>
      <section aria-labelledby="about-license">
        <h3 id="about-license" class="mb-1 font-medium">License</h3>
        <pre class="mono bg-muted/40 max-h-40 overflow-auto rounded-md border p-2.5 text-[11.5px] whitespace-pre-wrap">{license.trim()}</pre>
      </section>
      <section aria-labelledby="about-notices">
        <h3 id="about-notices" class="mb-1 font-medium">Third-party notices</h3>
        <p class="text-muted-foreground mb-1.5 text-[12.5px]">
          Open source software included in this app, with each license text. The same file,
          <span class="mono">THIRD_PARTY_NOTICES.md</span>, comes with the installers and every release.
        </p>
        <!-- Focusable so keyboard users can scroll the long text (WCAG 2.1.1). -->
        <!-- svelte-ignore a11y_no_noninteractive_tabindex -->
        <pre
          class="mono bg-muted/40 h-64 overflow-auto rounded-md border p-2.5 text-[11.5px] whitespace-pre-wrap"
          tabindex="0"
          aria-label="Third-party notices"
          aria-busy={notices === null && !failed}>{#if notices !== null}{notices}{:else if failed}Could not load the notices. They are in THIRD_PARTY_NOTICES.md in the GitHub repository.{:else}Loading...{/if}</pre>
      </section>
    </div>
    <Dialog.Footer>
      <Button onclick={() => (open = false)}>Close</Button>
    </Dialog.Footer>
  </Dialog.Content>
</Dialog.Root>
